"""CSV encoding for the transaction export: RFC 4180, UTF-8 with a BOM, formula-injection guard."""

import csv
import io
from collections.abc import Iterable, Iterator
from dataclasses import astuple, fields

from kori.transactions.service import ExportRow

COLUMNS = [f.name for f in fields(ExportRow)]
BOM = "﻿"
_DANGEROUS_START = ("=", "+", "-", "@", "\t", "\r")
# Columns that hold free text. date, type, amount, source and id are generated by Kori.
_TEXT = {"category", "merchant", "note", "payment_method", "tags"}


def guard(value: str) -> str:
    """Stop spreadsheets from running a cell as a formula."""
    return "'" + value if value.startswith(_DANGEROUS_START) else value


def encode_rows(rows: Iterable[ExportRow]) -> Iterator[bytes]:
    buf = io.StringIO(newline="")
    writer = csv.writer(buf, lineterminator="\r\n")
    writer.writerow(COLUMNS)
    buf.seek(0)
    yield (BOM + buf.read()).encode("utf-8")
    for row in rows:
        buf.seek(0)
        buf.truncate()
        writer.writerow(
            guard(v) if name in _TEXT else v for name, v in zip(COLUMNS, astuple(row), strict=True)
        )
        yield buf.getvalue().encode("utf-8")
